<template>
  <div class="page-shell"><header class="page-header"><div><el-tag>第 2 步 / 4</el-tag><h1>岗位智能建模</h1><p>从岗位模板或 JD 文本中生成动态胜任力模型</p></div><el-button @click="router.push('/resume-analysis')">上一步</el-button></header>
    <el-steps :active="1" finish-status="success" class="flow"><el-step title="简历分析"/><el-step title="岗位建模"/><el-step title="人岗匹配"/><el-step title="评估方案"/></el-steps>
    <el-row :gutter="20"><el-col :xs="24" :lg="9"><el-card shadow="never"><template #header><strong>岗位来源</strong></template><el-radio-group v-model="mode"><el-radio-button value="template">选择岗位模板</el-radio-button><el-radio-button value="jd">输入 JD 文本</el-radio-button></el-radio-group>
      <div v-if="mode==='template'" class="input-block"><el-select v-model="selectedTemplate" placeholder="请选择岗位" style="width:100%"><el-option v-for="item in templates" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-alert v-if="activeTemplate" :title="activeTemplate.name" :description="activeTemplate.description" type="info" :closable="false" class="tip"/></div>
      <el-input v-else v-model="jd" type="textarea" :rows="12" class="input-block" placeholder="粘贴岗位职责、技能和经验要求..."/>
      <el-button type="primary" size="large" class="wide" :loading="loading" @click="analyze">AI 解析岗位并生成模型</el-button></el-card></el-col>
      <el-col :xs="24" :lg="15"><el-card shadow="never" v-loading="loading"><template #header><div class="card-title"><strong>岗位画像</strong><el-tag v-if="job.name" type="success">模型已生成</el-tag></div></template><el-empty v-if="!job.name" description="请选择岗位来源并生成岗位模型"/><template v-else><h2>{{ job.name }} <el-tag>{{ job.level }}</el-tag></h2><el-row :gutter="16"><el-col :span="12"><h3>岗位职责</h3><ul><li v-for="item in job.responsibilities" :key="item">{{ item }}</li></ul></el-col><el-col :span="12"><h3>技能要求</h3><ul><li v-for="item in job.requirements" :key="item">{{ item }}</li></ul></el-col></el-row><h3>经验要求</h3><el-tag v-for="item in job.experienceRequirements" :key="item" class="requirement" type="info">{{ item }}</el-tag><h3>动态胜任力模型</h3><el-table :data="store.competencyModel" border><el-table-column prop="name" label="能力维度"/><el-table-column prop="weight" label="岗位权重"><template #default="{row}">{{ row.weight }}%</template></el-table-column><el-table-column prop="targetScore" label="目标分"/><el-table-column label="评估状态"><template #default><el-tag type="warning">待匹配</el-tag></template></el-table-column></el-table><div class="actions"><el-button type="primary" size="large" @click="generateMatch">生成岗位匹配</el-button></div></template></el-card></el-col></el-row>
  </div>
</template>
<script setup>
import { computed,onMounted,ref } from "vue";import { useRouter } from "vue-router";import { ElMessage } from "element-plus";import { getJobTemplates,parseJob } from "@/api/job";import { useAssessmentStore } from "@/store/assessment";
const router=useRouter();const store=useAssessmentStore();const mode=ref("template");const templates=ref([]);const selectedTemplate=ref("JOB-AI-APP-001");const jd=ref("负责 AI 应用前端交互、大模型 API 接入及服务端联调；熟悉 Vue 3、提示词设计和基础后端开发。");const loading=ref(false);const job=computed(()=>store.session.jobProfile||{});const activeTemplate=computed(()=>templates.value.find(i=>i.id===selectedTemplate.value));
onMounted(async()=>{templates.value=await getJobTemplates()});const analyze=async()=>{loading.value=true;try{const input=mode.value==='jd'?jd.value:activeTemplate.value?.description;const result=await parseJob(input);store.setJobProfile(result.jobProfile);store.setCompetencyModel(result.competencyModel);ElMessage.success("岗位画像与 5 维胜任力模型生成完成")}finally{loading.value=false}};const generateMatch=()=>{store.persist();router.push('/job-match')};
</script>
<style scoped>.page-shell{min-height:100vh;padding:32px 5%;background:#f5f7fa}.page-header,.card-title{display:flex;justify-content:space-between;align-items:center}.page-header h1{margin:10px 0 4px}.page-header p{color:#909399}.flow{margin:28px 0 34px}.input-block{margin-top:20px}.tip{margin-top:16px}.wide{width:100%;margin-top:20px}h2{margin-top:0}h3{margin:22px 0 12px}li{margin:9px 0;color:#606266}.requirement{margin:4px;white-space:normal;height:auto;padding:7px}.actions{text-align:right;margin-top:24px}@media(max-width:992px){.el-col{margin-bottom:16px}}</style>
